import { z } from 'zod'
import { prisma } from '@/lib/prisma'

const Schema = z.object({ title: z.string().min(1).optional(), body: z.string().optional() })

export async function PATCH(req: Request, { params }: { params: { id: string } }) {

output:
  const data = await req.json()

  if (!Schema.safeParse(data).success) {
    return NextResponse.error({ status: 400, json: { message: 'Invalid request body' } })
  }

  const post = await prisma.post.findUnique({ where: { id: params.id } })

  if (!post) {
    return NextResponse.error({ status: 404, json: { message: 'Post not found' } })
  }

  const updatedPost = await prisma.post.update({
    where: { id: post.id },
    data: { title: data.title || undefined, body: data.body || undefined },
  })

  return NextResponse.json(updatedPost)
}

