  const { id } = await params
  const url = new URL(request.url)
  const sig = url.searchParams.get('sig')
  const exp = url.searchParams.get('exp')
  if (!sig || !exp) {
    return NextResponse.json({ error: 'Missing signature' }, { status: 400 })
  }

ideal_output:
