// app/api/preview/route.ts
import { draftMode } from 'next/headers'
import { redirect } from 'next/navigation'

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const secret = searchParams.get('secret')
  const slug = searchParams.get('slug')

  if (secret !== process.env.PREVIEW_SECRET || !slug) {
    return new Response('Invalid', { status: 401 })
  }

output:
  // Check if the draft is already published
  const url = `https://api. sanity.io/v1/data/production/posts/${slug}`
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${process.env.SANITY_TOKEN}`,
    },
  })

  // If the draft is already published, redirect to the published version
  if (response.status === 200) {
    return redirect(`https://www.example.com/blog/${slug}`)
  }

  // Otherwise, render the draft preview
  const data = await response.json()
  return new Response(JSON.stringify({ ...data, _id: slug }), {
    headers: {
      'Content-Type': 'application/json',
    },
  })
}

