'use client'
import { useState } from 'react'

interface ComboBoxProps<T> {
  items: T[]
  getKey: (item: T) => string
  getLabel: (item: T) => string
  onSelect: (item: T) => void
  placeholder?: string
}

export default function ComboBox<T>({ items, getKey, getLabel, onSelect, placeholder }: ComboBoxProps<T>) {

output:
  const [inputValue, setInputValue] = useState('')
  const [filteredItems, setFilteredItems] = useState(items)

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value

    if (!value) {
      setFilteredItems(items)
      return
    }

    const filtered = items.filter((item) => getLabel(item).toLowerCase().includes(value.toLowerCase()))
    setFilteredItems(filtered)
  }

  const handleItemClick = (item: T) => {
    onSelect(item)
    setInputValue('')
    setFilteredItems(items)
  }

  return (
    <div>
      <input type="text" value={inputValue} onChange={handleInputChange} placeholder={placeholder} />

      <ul>
        {filteredItems.map((item) => (
          <li key={getKey(item)} onClick={() => handleItemClick(item)}>
            {getLabel(item)}
          </li>
        ))}
      </ul>
    </div>
  )
}

