context.prefix:
'use client'
import { useState } from 'react'

interface Column<T> {
  key: keyof T
  label: string
  render?: (value: T[keyof T], row: T) => React.ReactNode
}

interface DataTableProps<T> {
  data: T[]
  columns: Column<T>[]
  rowKey: (row: T) => string
}

export default function DataTable<T>({ data, columns, rowKey }: DataTableProps<T>) {

output:
  const [sortKey, setSortKey] = useState<keyof T | null>(null)

  return (
    <table>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column.key} onClick={() => setSortKey(column.key)}>
              {column.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.sort((a, b) => {
          if (sortKey === null) return 0

          const aValue = a[sortKey]
          const bValue = b[sortKey]

          if (typeof aValue === 'string') {
            return aValue.localeCompare(bValue)
          } else if (typeof aValue === 'number') {
            return aValue - bValue
          } else {
            throw new Error('Unsupported type for sorting')
          }
        }).map((row) => (
          <tr key={rowKey(row)}>
            {columns.map((column) => {
              const value = column.render ? column.render(row[column.key], row) : row[column.key]
              return <td key={column.key}>{value}</td>
            })}
          </tr>
        ))}
      </tbody>
    </table>
  )
}

