export async function archiveOrderWithChildren(input: unknown) {

context.prefix:
// app/actions/order/archive-cascade.ts
'use server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveOrderWithChildren(input: unknown) {

output:
  const parsedInput = Schema.parse(input)

  // Find the order and its children
  const order = await prisma.order.findUnique({
    where: { id: parsedInput.id },
    include: {
      items: true,
      payments: true,
      shippingAddress: true,
      billingAddress: true,
    },
  })

  if (!order) {
    throw new Error('Order not found')
  }

  // Archive the order and its children
  await prisma.order.update({
    where: { id: order.id },
    data: {
      archivedAt: new Date(),
    },
  })

  // Revalidate the paths for the order and its items
  revalidatePath('/orders/[id]', parsedInput.id)
  order.items.forEach((item) => revalidatePath('/orders/[id]/items/[id]', `${parsedInput.id}/${item.id}`))

  return { message: 'Order archived successfully' }
}

