'use server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveInvoiceWithChildren(input: unknown) {

output:
  const parsedInput = Schema.parse(input)

  // Recursively archive children invoices
  const childrenInvoices = await prisma.invoice.findMany({
    where: {
      parent_id: parsedInput.id,
    },
  })

  for (const child of childrenInvoices) {
    await archiveInvoiceWithChildren({ id: child.id })
  }

  // Archive the current invoice and revalidate paths
  await prisma.invoice.update({
    where: { id: parsedInput.id },
    data: {
      is_archived: true,
    },
  })

  await revalidatePath('/[slug]')
}

