export async function archiveProjectWithChildren(input: unknown) {

output:
  const parsedInput = Schema.parse(input)

  // Recursively archive all children projects
  const children = await prisma.project.findMany({
    where: {
      parent: {
        id: parsedInput.id,
      },
    },
  })

  for (const child of children) {
    await archiveProjectWithChildren({ id: child.id })
  }

  // Archive the project itself
  const project = await prisma.project.update({
    where: {
      id: parsedInput.id,
    },
    data: {
      isArchived: true,
    },
  })

  // Revalidate all paths that include this project's ID
  revalidatePath(`/${project.id}`)

  return project
}

