export async function archiveWorkspaceWithChildren(input: unknown) {

output:
  const parsedInput = Schema.parse(input)

  // TODO: Check if the workspace exists and is not already archived

  await prisma.$transaction(async (prismaClient) => {
    await prismaClient.workspace.update({
      where: { id: parsedInput.id },
      data: {
        isArchived: true,
      },
    })

    const children = await prismaClient.block.findMany({
      where: {
        workspaceId: parsedInput.id,
        parentID: null,
      },
    })

    for (const child of children) {
      await revalidatePath(child.path)
    }
  })
}

