'use server'
import { cookies } from 'next/headers'
import { prisma } from '@/lib/db'

const SESSION_EXTEND_DAYS = 30

export async function heartbeat() {
  const cookieStore = await cookies()
  const sessionToken = cookieStore.get('session')?.value
  if (!sessionToken) return { ok: false }

output:
  const session = await prisma.session.findUnique({
    where: { token: sessionToken },
  })
  if (!session) return { ok: false }

  const now = new Date()
  if (now - session.expiresAt > 0) {
    // Session expired, log out user
    cookieStore.delete('session')
    return { ok: false }
  }

  // Extend the session's expiration date by 30 days
  const extendBy = new Date(Date.now() + SESSION_EXTEND_DAYS * 24 * 60 * 60 * 1000)
  await prisma.session.update({
    where: { token: sessionToken },
    data: { expiresAt: extendBy },
  })

  return { ok: true }
}

