// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private events: E

  constructor(events: E) {
    this.events = events
  }

  on<K extends keyof E>(name: K, listener: (...args: E[K]) => void): this {
    // @ts-expect-error
    this.events[name] = listener

    return this
  }

  off<K extends keyof E>(name: K, listener?: (...args: E[K]) => void): this {
    if (listener) {
      // @ts-expect-error
      this.events[name] = undefined
    } else {
      delete this.events[name]
    }

    return this
  }

  emit<K extends keyof E>(name: K, ...args: E[K]): boolean {
    const listener = this.events[name] as (...args: unknown[]) => void

    if (listener) {
      listener(...args)

      return true
    } else {
      return false
    }
  }
}

