/**
 * Retry an async function with exponential backoff up to maxAttempts
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 500
): Promise<T> {

output:
  let attempts = 0;

  while (true) {
    try {
      return await fn();
    } catch (err) {
      if (attempts >= maxAttempts - 1) {
        throw err;
      }

      const delay = Math.pow(2, attempts) * baseDelayMs;
      attempts += 1;

      console.log(`Retrying in ${delay}ms...`);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}

